#!/usr/bin/env bash
set -euo pipefail
if [ "$(id -u)" = 0 ]; then exec setpriv --reuid=7777 --regid=7777 --clear-groups env HOME=/tmp bash "$0"; fi
DIR=$(mktemp -d); PORT=55438
unset PGHOST PGPORT PGUSER PGPASSWORD PGDATABASE PGSSLMODE
initdb -D "$DIR" -U postgres >/dev/null
pg_ctl -D "$DIR" -o "-p $PORT -k $DIR -c listen_addresses=''" -l "$DIR/log" start >/dev/null
trap 'pg_ctl -D "$DIR" stop -m immediate >/dev/null; rm -rf "$DIR"' EXIT
P="psql -X -q -v ON_ERROR_STOP=1 -h $DIR -p $PORT -U postgres -d postgres"
$P <<'SQL'
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth; CREATE SCHEMA storage;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email_confirmed_at timestamptz);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('test.uid',true),'')::uuid$$;
CREATE FUNCTION public.has_role(uuid,text) RETURNS boolean LANGUAGE sql AS $$SELECT $1='99999999-9999-4999-8999-999999999999'::uuid$$;
CREATE TABLE storage.objects(bucket_id text,name text); ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY; GRANT SELECT ON storage.objects TO authenticated;
GRANT USAGE ON SCHEMA auth,storage TO authenticated,anon;
CREATE TABLE public.customer_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reviewer_name text,review_text text,location text,published boolean DEFAULT false,featured boolean DEFAULT false,archived boolean DEFAULT false,rating int,sort_order int);
GRANT SELECT ON public.customer_reviews TO authenticated,anon;
CREATE TABLE public.member_welcome_email_queue(user_id uuid,completed_at timestamptz);
CREATE TABLE public.discount_codes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE,code_kind text,discount_type text,value numeric,max_uses int,times_used int DEFAULT 0,user_id uuid,note text,min_spend_cents int,combine_multibuy boolean,combine_crypto boolean,combine_credit boolean,active boolean DEFAULT true,expires_at timestamptz,created_at timestamptz DEFAULT now());
INSERT INTO public.discount_codes(code,code_kind,discount_type,value,max_uses,times_used,note,expires_at,combine_multibuy) VALUES('CUSTOM','referral','fixed',7,91,8,'keep',now()+interval '1 day',false),('VOUCHER','member','fixed',19,1,0,'reward',NULL,true);
CREATE TABLE protected_before AS SELECT id,to_jsonb(d)-'discount_type'-'value' AS protected FROM public.discount_codes d WHERE code_kind='referral';
SQL
$P -f drizzle/migrations/0062_referral_ten_percent_issuance.sql
$P -f scripts/referral-ten-percent-rollout.sql
q() { $P -tA -c "$1"; }
check() { if [ "$2" != "$3" ]; then echo "FAIL $1: $2 != $3"; exit 1; fi; echo "PASS $1"; }
check "in-place rollout preserves all other fields" "$(q "select bool_and((to_jsonb(d)-'discount_type'-'value')=b.protected) from discount_codes d join protected_before b using(id)")" t
check "current custom referral becomes percent ten" "$(q "select discount_type||':'||value from discount_codes where code='CUSTOM'")" percent:10
check "earned voucher unchanged" "$(q "select discount_type||':'||value from discount_codes where code='VOUCHER'")" fixed:19
q "UPDATE discount_codes SET code='RENAMED',discount_type='fixed',value=13 WHERE code='CUSTOM'"
$P -f scripts/referral-ten-percent-rollout.sql
check "repeated rollout preserves later custom rename/type/value" "$(q "select discount_type||':'||value from discount_codes where code='RENAMED'")" fixed:13
U=11111111-1111-4111-8111-111111111111
q "INSERT INTO auth.users VALUES('$U',now()); INSERT INTO member_welcome_email_queue VALUES('$U',NULL)"
C=$(q "select allocate_welcome_referral_code('$U')")
check "future autogenerated percent ten" "$(q "select discount_type||':'||value from discount_codes where code='$C'")" percent:10
q "UPDATE discount_codes SET code='PERSONAL',value=17 WHERE code='$C'"
check "allocator reuses custom code without reset" "$(q "select allocate_welcome_referral_code('$U')")" PERSONAL
check "custom discount survives allocator" "$(q "select value from discount_codes where code='PERSONAL'")" 17
$P -f drizzle/migrations/0063_moderated_member_review_photos.sql
$P -f drizzle/migrations/0064_review_photo_cleanup_retry_safety.sql
I=aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa; OTHER=22222222-2222-4222-8222-222222222222
q "INSERT INTO review_photo_uploads(id,user_id,storage_path,mime_type,byte_size,ready) VALUES('$I','$U','$U/$I.png','image/png',100,true)"
check "pending photos private from anon" "$(q "set role anon; select count(*) from review_photo_uploads")" 0
check "owner reads pending photo" "$(q "set role authenticated; set test.uid='$U'; select count(*) from review_photo_uploads")" 1
check "other member cannot read pending photo" "$(q "set role authenticated; set test.uid='$OTHER'; select count(*) from review_photo_uploads")" 0
check "admin reads pending photo" "$(q "set role authenticated; set test.uid='99999999-9999-4999-8999-999999999999'; select count(*) from review_photo_uploads")" 1
REVIEW='{"reviewer_name":"Isolated test","review_text":"Isolated database validation only","location":""}'
check "other member cannot link owned upload" "$(q "select submit_member_photo_review('$OTHER','$REVIEW',ARRAY['$I'::uuid])" 2>/dev/null || echo REJECTED)" REJECTED
R=$(q "select submit_member_photo_review('$U','$REVIEW',ARRAY['$I'::uuid])")
check "linked review starts unapproved unrated" "$(q "select published::text||':'||(rating is null)::text from customer_reviews where id='$R'")" false:true
check "photo linked durably" "$(q "select review_id='$R'::uuid from review_photo_uploads where id='$I'")" t
check "cleanup cannot remove linked photo" "$(q "select count(*) from claim_review_photo_cleanup('$U',ARRAY['$I'::uuid])")" 0
q "update customer_reviews set published=true where id='$R'"
check "approved photo public" "$(q "set role anon; select count(*) from review_photo_uploads")" 1
q "update customer_reviews set archived=true where id='$R'"
check "archiving revokes public photo" "$(q "set role anon; select count(*) from review_photo_uploads")" 0
check "member cannot call privileged link directly" "$(q "set role authenticated; select submit_member_photo_review('$U','$REVIEW',ARRAY['$I'::uuid])" 2>/dev/null || echo REJECTED)" REJECTED
check "arbitrary paths rejected" "$(q "insert into review_photo_uploads(user_id,storage_path,mime_type,byte_size) values('$U','../other.png','image/png',1)" 2>/dev/null || echo REJECTED)" REJECTED
check "executable types rejected" "$(q "insert into review_photo_uploads(user_id,storage_path,mime_type,byte_size) values('$U','bad','text/html',1)" 2>/dev/null || echo REJECTED)" REJECTED
check "oversize files rejected" "$(q "insert into review_photo_uploads(user_id,storage_path,mime_type,byte_size) values('$U','bad','image/png',5242881)" 2>/dev/null || echo REJECTED)" REJECTED
J=bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb
q "insert into review_photo_uploads(id,user_id,storage_path,mime_type,byte_size,ready) values('$J','$U','$U/$J.png','image/png',1,true)"
check "other owner cleanup rejected" "$(q "select count(*) from claim_review_photo_cleanup('$OTHER',ARRAY['$J'::uuid])")" 0
check "orphan cleanup claimed" "$(q "select count(*) from claim_review_photo_cleanup('$U',ARRAY['$J'::uuid])")" 1
check "storage failure cleanup remains retryable" "$(q "select count(*) from claim_review_photo_cleanup('$U',ARRAY['$J'::uuid])")" 1
check "cleanup claim prevents late linkage" "$(q "select submit_member_photo_review('$U','$REVIEW',ARRAY['$J'::uuid])" 2>/dev/null || echo REJECTED)" REJECTED
echo 'Isolated referral and photo database checks passed; no project reviews created.'